Section Call.
Variables (R : bvmap 5 word) (M0 : word -> option byte) (model : Model) (K : TSet) (LBX : list (Z * Z)) (cr : credit)
          (sp r fb cat n : Z) (s : PQM.mpst) (st : NEM.aest) (str : PM.vstr) (sm : PM.strm) (e eb : bool).
Definition op : Z := fb + 32.
Definition ois : Z := fb + 616.
Definition oa : Z := fb + 432.
Definition oec : Z := fb + 8.
Definition ov : Z := fb + 536.
Definition osk : Z := fb + 592.
Abbreviation ae_at := (NEM.ae_at RSEGS AD AE L PMSP.T3 PMSP.T4 (qa_vp_adaptor AQ)).

(* [comment removed for export] *)
Definition LPPRE : Prop :=
  hi_heap HI (PNRN.mown s st ++ LBX) cr M0 (m_vmmaps model) /\ PMSP.model_ok model /\ K []
  /\ getr R (PMK.reg 1) = Z_to_bv 64 r /\ L5.ra_ok r /\ getr R (PMK.reg 2) = Z_to_bv 64 sp
  /\ getr R (PMK.reg 3) = Z_to_bv 64 (pa_gp AD) /\ getr R (PMK.reg 4) = Z_to_bv 64 (pa_tp AD) /\ L5C.stk (hl_sptop L) M0 sp SCR
  /\ sp <= fb /\ fb + 928 <= hl_sptop L /\ fb mod 16 = 0
  /\ getr R (PMK.reg 10) = Z_to_bv 64 op /\ getr R (PMK.reg 11) = Z_to_bv 64 oa /\ getr R (PMK.reg 12) = Z_to_bv 64 oec
  /\ PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M0 op ois s
  /\ ae_at M0 oa ov osk st
  /\ PM.iss_at RSEGS AD PMSP.T3 M0 ois str sm /\ L5.u64_at RSEGS M0 (op + 496) oa
  /\ PMST.base_ok RSEGS AD M0 /\ PQST.err_ok RSEGS AD AQ M0 e /\ PQM.mgrow_ok s /\ NEM.ae_ok st /\ PQM.cpl s (NEM.ae_a st) /\ PQM.acct n s (NEM.ae_a st) sm
  /\ incl (PM.vs_own str) LBX /\ PQR.minv_d 0 s /\ NEM.ec_state RSEGS AD M0 oec eb cat
  /\ PMSP.credit_le (PM.credit_add (PNRN.pot_run L s st) PNRN.TSRES_ME) cr
  /\ NEM.oacct n s st sm /\ NEM.ebound st /\ (eb = false -> NEM.bal st).
Definition LPKONT : Prop :=
  forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (s' : PQM.mpst) (st' : NEM.aest)
         (sm' : PM.strm) (e' b' : bool) (cr' : credit),
    regs_preserved R R' ->
    PNRN.parse_post RSEGS AD AQ AE L M' fb s s' st' str sm sm' e e' b' cat ->
    L5C.hpres L LBX sp (PMSP.pm_scr 11) (PNRN.W_mrun AD AQ AE fb) M0 M' ->
    PMSP.credit_keep cr cr' (PNRN.pot_run L s st) PMSP.cr0 ->
    model_but_vm model model' -> hi_heap HI (PNRN.mown s' st' ++ LBX) cr' M' (m_vmmaps model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

Hypothesis PRE : LPPRE.
Hypothesis KONT : LPKONT.

(* [comment removed for export] *)
Local Ltac unpack := destruct PRE as (HH & MK & KK & R1 & RA & R2 & R3 & R4 & STK & F1 & F2 & F3 & A10 & A11 & A12 & PA & AA & IA & VR & BA & ER
                                     & GR & AO & CP & AC & IN & IV & EC & CR & OAC & EBD & BL).
