  PM.iss_at RSEGS AD PMSP.T3 M1 ois str sm1 /\ L5.u64_at RSEGS M1 (op + 496) oa
  /\ PMST.base_ok RSEGS AD M1 /\ PQST.err_ok RSEGS AD AQ M1 e1.
