Lemma otx_keep LBc sp' scr' W' M1 M2 sm1 e1 :
  PMK.ek L LBc sp' scr' W' M1 M2 -> L5C.stk (hl_sptop L) M1 sp' scr' -> 0 <= scr' -> PMFR.brange L LBc -> incl (PM.vs_own str) LBc ->
