(* [comment removed for export] *)
Lemma world_frzx M1 M2 sm1 e1 (P : Z -> Prop) :
  L5C.stk (hl_sptop L) M1 sp SCR ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ P i -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) ->
  (forall a, P a -> (sp - SCR <= a < sp) \/ (op <= a < op + 400)
                   \/ (a < hl_ceil L /\ (a < hl_img_lo L \/ hl_img_hi L <= a) /\ ~ in_block (NEM.aeown st ++ LBX) a)) ->
  ae_at M1 oa ov osk st -> otx M1 sm1 e1 ->
  ae_at M2 oa ov osk st /\ otx M2 sm1 e1.
