(* [comment removed for export] *)
Lemma mparser_upd2 M M' s1 m' dn' d' stk' :
  PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M op ois s1 -> 0 <= op -> op + 400 <= 2 ^ 64 ->
  L5C.agree_on M M' op 8 -> L5C.agree_on M M' (op + 16) 360 ->
  PMPK.dkr M M' (op + 8) 8 -> PMPK.dkr M M' (op + 376) 24 ->
  L5.u8_at RSEGS M' (op + 8) m' -> (m' = 0 \/ m' = 1) -> L5.u8_at RSEGS M' (op + 9) dn' -> (dn' = 0 \/ dn' = 1) ->
  L5.u32_at RSEGS M' (op + 12) d' -> 0 <= d' <= PQM.MAX_DEPTH + 1 ->
  PQM.mvec_at RSEGS PMSP.T3 PMSP.T4 M' (op + 376) (PQM.p_sb s1) (PQM.p_sk s1) stk' ->
  PMPK.dkr M M' (PM.sr_qc (PQM.p_src s1)) PM.CHUNK ->
  (forall c n0 p, PQM.p_tb s1 = PM.VLong c n0 p -> PMPK.dkr M M' p c) ->
  (forall b n0 c, PQM.p_bb s1 = PQV8.V8Blk b n0 c -> PMPK.dkr M M' b c) ->
