(* [comment removed for export] *)
Lemma mvec_set_last M M' v b k stk c c' :
  PQM.mvec_at RSEGS PMSP.T3 PMSP.T4 M v b k (stk ++ [c]) ->
  0 <= v -> v + 24 <= 2 ^ 64 -> 0 <= b -> b + 24 * 2 ^ k <= 2 ^ 64 ->
  L5C.agree_on M M' v 24 -> L5C.agree_on M M' b (24 * Z.of_nat (length stk)) -> L5.defined M' b (24 * 2 ^ k) ->
  PQM.mstate_at RSEGS M' (b + 24 * Z.of_nat (length stk)) c' ->
  PQM.mvec_at RSEGS PMSP.T3 PMSP.T4 M' v b k (stk ++ [c']).
