(* [comment removed for export] *)
Lemma mvec_pop M M' v b k stk c :
  PQM.mvec_at RSEGS PMSP.T3 PMSP.T4 M v b k (stk ++ [c]) ->
  0 <= v -> v + 24 <= 2 ^ 64 -> 0 <= b -> b + 24 * 2 ^ k <= 2 ^ 64 ->
  L5C.agree_on M M' v 8 -> L5C.agree_on M M' (v + 16) 8 -> L5C.agree_on M M' b (24 * 2 ^ k) ->
  L5.u64_at RSEGS M' (v + 8) (b + 24 * Z.of_nat (length stk)) ->
