(* [comment removed for export] *)
Lemma shape_top stk : PQR.mstack_shape stk ->
  exists pre top, stk = pre ++ [top] /\ PQM.mstate_ok top
    /\ ((pre = [] /\ PQM.mode_bottom (PQM.ms_mode top)) \/ (pre <> [] /\ PQM.mode_cont (PQM.ms_mode top) /\ PQR.mstack_shape pre)).
Proof.
