Lemma shape_set_last pre top top' : PQR.mstack_shape (pre ++ [top]) -> PQM.mstate_ok top' ->
  (pre = [] -> PQM.mode_bottom (PQM.ms_mode top')) -> (pre <> [] -> PQM.mode_cont (PQM.ms_mode top')) ->
  PQR.mstack_shape (pre ++ [top']).
