(* [comment removed for export] *)
Definition LS (M1 : word -> option byte) (s1 : PQM.mpst) (st1 : NEM.aest) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) (model1 : Model) : Prop :=
  PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M1 op ois s1
  /\ ae_at M1 oa ov osk st1 /\ otx M1 sm1 e1 /\ PQM.mgrow_ok s1
  /\ NEM.ae_ok st1 /\ PQM.cpl s1 (NEM.ae_a st1) /\ PQM.acct n s1 (NEM.ae_a st1) sm1 /\ NEM.oacct n s1 st1 sm1 /\ NEM.ebound st1
  /\ (e = true -> e1 = true) /\ PMSP.src_step (PQM.p_src s) (PQM.p_src s1) sm sm1
  /\ saved M1 /\ cm M1 /\ PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st1) /\ model_but_vm model model1
  /\ hi_heap HI (PNRN.mown s1 st1 ++ LBX) cr1 M1 (m_vmmaps model1).

