Lemma FIN (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (st1 : NEM.aest)
      (sm1 : PM.strm) (e1 b1 : bool) (cr1 : credit) :
  getr R1 (PMK.reg 1) = getr R (PMK.reg 1) -> (forall x, In x PMK.cs_all -> getr R1 (PMK.reg x) = getr R (PMK.reg x)) ->
  PNRN.parse_post RSEGS AD AQ AE L M1 fb s s1 st1 str sm sm1 e e1 b1 cat ->
  cm M1 -> PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st1) ->
  0 <= fst (PNRN.pot_run L s1 st1) -> 0 <= snd (PNRN.pot_run L s1 st1) ->
  model_but_vm model model1 -> hi_heap HI (PNRN.mown s1 st1 ++ LBX) cr1 M1 (m_vmmaps model1) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x4572c M1 model1) K.
