(* [comment removed for export] *)
Definition RQ (R3 : bvmap 5 word) (M3 : word -> option byte) (s2 s3 : PQM.mpst) (st1 st3 : NEM.aest) (sm2 sm3 : PM.strm) (e2 e3 b2 b3 : bool) (cr3 : credit)
           (model3 : Model) : Prop :=
  PNRN.mrun_post_d RSEGS AD AQ AE L 0 PNRN.mprog_item R3 M3 fb s2 s3 st1 st3 str sm2 sm3 e2 e3 b2 b3 cat n
  /\ (e = true -> e2 = true) /\ PMSP.src_step (PQM.p_src s) (PQM.p_src s2) sm sm2
  /\ saved M3 /\ cm M3 /\ PMSP.credit_keep cr cr3 (PNRN.pot_run L s st) (PNRN.pot_run L s3 st3) /\ model_but_vm model model3
  /\ hi_heap HI (PNRN.mown s3 st3 ++ LBX) cr3 M3 (m_vmmaps model3).

(* [comment removed for export] *)
Lemma RICALL (rr : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model)
      (s1 : PQM.mpst) (st1 : NEM.aest) (sm1 : PM.strm) (e1 b1 : bool) (cr1 : credit) :
  PNRN.read_item_spec RSEGS AD AQ AE L HI ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 rr -> L5.ra_ok rr -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 112) ->
  getr R1 (PMK.reg 10) = Z_to_bv 64 op -> getr R1 (PMK.reg 11) = Z_to_bv 64 oa -> getr R1 (PMK.reg 12) = Z_to_bv 64 oec ->
  getr R1 (PMK.reg 3) = getr R (PMK.reg 3) -> getr R1 (PMK.reg 4) = getr R (PMK.reg 4) ->
  LS M1 s1 st1 sm1 e1 cr1 model1 -> PQR.minv_d 0 s1 -> NEM.ec_state RSEGS AD M1 oec b1 cat -> (b1 = false -> NEM.bal st1) ->
  (forall (fx3 : FPState) (R3 : bvmap 5 word) (M3 : word -> option byte) (model3 : Model) (s3 : PQM.mpst) (st3 : NEM.aest) (sm3 : PM.strm)
          (e3 b3 : bool) (cr3 : credit),
     regs_preserved R1 R3 -> RQ R3 M3 s1 s3 st1 st3 sm1 sm3 e1 e3 b1 b3 cr3 model3 -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx3 R3 rr M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x457a8 M1 model1) K.
