  /\ NEM.ae_ok st2 /\ NEM.nlv st2 = NEM.nlv st1 + dl /\ NEM.kbsize st2 <= NEM.kbsize st1 + 2 /\ NEM.phi st2 <= NEM.phi st1 + 6 /\ NEM.ebound st2
  /\ (e = true -> e1 = true) /\ PMSP.src_step (PQM.p_src s) (PQM.p_src s1) sm sm1
  /\ (exists b2 : bool, NEM.ec_state RSEGS AD M2 oec b2 cat /\ (b2 = false -> NEM.bal st2))
  /\ saved M2 /\ cm M2 /\ PMSP.credit_keep cr cr2 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st2) /\ model_but_vm model model2
  /\ hi_heap HI (PNRN.mown s1 st2 ++ LBX) cr2 M2 (m_vmmaps model2).

