Lemma EVCALL (pcv : Z) (args : bvmap 5 word -> (word -> option byte) -> Z -> Z -> Z -> list (Z * Z) -> Prop)
      (pre : bvmap 5 word -> (word -> option byte) -> NEM.aest -> Prop) (step : bvmap 5 word -> (word -> option byte) -> NEM.aest -> NEM.aest -> bool -> bool -> Prop)
      (dl rr : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model) (s1 : PQM.mpst) (st1 : NEM.aest) (sm1 : PM.strm) (e1 b1 : bool)
      (cr1 : credit) :
  PNV.vis_spec RSEGS AD AQ AE L HI pcv args pre step ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 rr -> L5.ra_ok rr -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 112) -> getr R1 (PMK.reg 10) = Z_to_bv 64 oa ->
  getr R1 (PMK.reg 3) = getr R (PMK.reg 3) -> getr R1 (PMK.reg 4) = getr R (PMK.reg 4) ->
  args R1 M1 (sp - 112) oa oec (PQM.mparser_own s1 ++ LBX) -> pre R1 M1 st1 ->
  (forall st' (bb bb' : bool), step R1 M1 st1 st' bb bb' ->
     NEM.nlv st' = NEM.nlv st1 + dl /\ NEM.kbsize st' <= NEM.kbsize st1 + 2 /\ NEM.phi st' <= NEM.phi st1 + 6 /\ NEM.esize st' <= NEM.esize st1
     /\ (NEM.esize st' - NEM.edepth st' = NEM.esize st1 - NEM.edepth st1 \/ bb' = true)) ->
  (dl = 0 \/ dl = -1) ->
  PQM.mparser_at RSEGS AD PMSP.T3 PMSP.T4 (pa_vp_parser AD) M1 op ois s1 ->
  ae_at M1 oa ov osk st1 -> otx M1 sm1 e1 -> PQM.mgrow_ok s1 -> NEM.ae_ok st1 -> NEM.ebound st1 ->
  (e = true -> e1 = true) -> PMSP.src_step (PQM.p_src s) (PQM.p_src s1) sm sm1 -> NEM.ec_state RSEGS AD M1 oec b1 cat -> (b1 = false -> NEM.bal st1) ->
  saved M1 -> cm M1 -> PMSP.credit_keep cr cr1 (PNRN.pot_run L s st) (PNRN.pot_run L s1 st1) -> model_but_vm model model1 ->
  hi_heap HI (PNRN.mown s1 st1 ++ LBX) cr1 M1 (m_vmmaps model1) ->
  (forall (fx2 : FPState) (R2 : bvmap 5 word) (M2 : word -> option byte) (model2 : Model) (st2 : NEM.aest) (e2 : bool) (cr2 : credit),
     regs_preserved R1 R2 -> RE dl M2 s1 st1 st2 sm1 e2 cr2 model2 -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 rr M2 model2) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pcv M1 model1) K.
