Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQH3.
Import PMS. Import PQH.
Local Ltac lia := PMK.alia.     (* [comment removed for export] *)

Section Stage.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LM : PQH.layoutM L.
Let KL := PMKS.klayout_S L LY.
Variable R0 : bvmap 5 word.
Variable M0 : word -> option byte.
Variable model0 : Model.
Variables (sp ra n : Z).
Variable LB0 : list (Z * Z).
Variable cr0 : credit.
Variable g : PMST.st.
Hypothesis Hn : 0 <= n < 2 ^ 26.
Hypothesis Hcr0 : PMSP.credit_le (PQTS.TOPK, PQTS.TOPB n) cr0.
Hypothesis Hgp : getr R0 (reg 3) = Z_to_bv 64 (pa_gp AD).
Hypothesis Htp : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).

Lemma stage3 :
  PQRH.reader_ctor_spec RSEGS AD AQ L HI ->
  forall (fx : FPState) R M model cr s s2 sm K,
    PQH.H2 L HI R0 M0 model0 sp ra n LB0 cr0 g R M model cr s s2 sm -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1 cr1 qc b b',
        PQH.H3 L HI R0 M0 model0 sp ra n LB0 cr0 g R1 M1 model1 cr1 s s2 sm qc b b' ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x39168 M1 model1) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x390f8 M model) K.
Proof using All.
