Hypothesis Htp : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).

Lemma stage4 :
  PMS.syscat_spec L HI -> PQR.reset_spec RSEGS AD AQ L HI ->
  forall (fx : FPState) R M model cr s s2 sm qc b b' K,
    PQH.H3 L HI R0 M0 model0 sp ra n LB0 cr0 g R M model cr s s2 sm qc b b' -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        PQH.H4 L HI R0 M0 model0 sp ra n LB0 cr0 g R1 M1 model1 cr s s2 sm qc b b' ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x3917c M1 model1) K) ->
