Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQH6.
Import PMS. Import PQH.
Local Ltac lia := PMK.alia.     (* [comment removed for export] *)

Section Stage.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PMKS.klayout_S L LY.
Variable R0 : bvmap 5 word.
Variable M0 : word -> option byte.
Variable model0 : Model.
Variables (sp ra n : Z).
Variable LB0 : list (Z * Z).
Variable cr0 : credit.
Variable g : PMST.st.
Hypothesis Hn : 0 <= n < 2 ^ 26.
Hypothesis Hgp : getr R0 (reg 3) = Z_to_bv 64 (pa_gp AD).
Hypothesis Htp : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).

Lemma stage6 :
  PQRH.reader_dtor_spec RSEGS AD AQ L HI ->
  forall (fx : FPState) R M model cr s s2 sm p st be K,
    PQH.H5 L HI R0 M0 model0 sp ra n LB0 cr0 g R M model cr s s2 sm p st be -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        PQH.H6 L HI R0 M0 model0 sp ra n LB0 cr0 g R1 M1 model1 cr s s2 sm (NEM.ae_e st) (NEM.ae_s st) be ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x39194 M1 model1) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x3918c M model) K.
