Lemma stage7 :
  PMS.opdel_spec L HI ->
  forall (fx : FPState) R M model cr s s2 sm en k be K,
    PQH.H6 L HI R0 M0 model0 sp ra n LB0 cr0 g R M model cr s s2 sm en k be -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        PQH.H7 L HI R0 M0 model0 sp ra n LB0 cr0 g R1 M1 model1 cr s s2 sm be ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x391c4 M1 model1) K) ->
