Definition H7b (R : bvmap 5 word) (M : word -> option byte) (model : Model) (cr : credit) (s : PM.vstr) (be : bool) : Prop :=
  PQH.hcore L R0 M0 model0 sp ra LB0 R M model /\ PQHK.vstr_at M (PQH.fb sp + 888) s
  /\ L5.u64_at RSEGS M (PQH.fb sp + 640) (pa_classic_imp AD)
  /\ (exists vp st, PM.iosb_at RSEGS AD PQH.T3 M (PQH.fb sp + 736) vp (PQH.fb sp + 632) st)
  /\ PQH.hstat M true true be /\ (PMST.st_err g = true -> be = true)
  /\ hi_heap HI (PM.vs_own s ++ LB0) cr M (m_vmmaps model)
  /\ PMSP.credit_keep cr0 cr (PQH.P0 L n) PMSP.cr0
  /\ getr R (reg 1) = Z_to_bv 64 234028 /\ getr R (reg 10) = Z_to_bv 64 (sp - 288).

Lemma strbuf_gone :
  PMS.opdel_spec L HI ->
  forall (fx : FPState) R M model cr s s2 sm be K,
    PQH.H7 L HI R0 M0 model0 sp ra n LB0 cr0 g R M model cr s s2 sm be -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        H7b R1 M1 model1 cr s be ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x90194 M1 model1) K) ->
