Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQH9.
Import PMS. Import PQH.
Local Ltac lia := PMK.alia.     (* [comment removed for export] *)

Section Stage.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PMKS.klayout_S L LY.
Variable R0 : bvmap 5 word.
Variable M0 : word -> option byte.
Variable model0 : Model.
Variables (sp ra n : Z).
Variable LB0 : list (Z * Z).
Variable cr0 : credit.
Variable g : PMST.st.
Hypothesis Hn : 0 <= n < 2 ^ 26.
Hypothesis Hcr0 : PMSP.credit_le (PQTS.TOPK, PQTS.TOPB n) cr0.
Hypothesis LM : PQH.layoutM L.
Hypothesis Hgp : getr R0 (reg 3) = Z_to_bv 64 (pa_gp AD).
Hypothesis Htp : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).
Hypothesis Hsp0 : getr R0 (reg 2) = Z_to_bv 64 sp.
Hypothesis Hra : L5.ra_ok ra.


(* [comment removed for export] *)
Definition H8f (R : bvmap 5 word) (M : word -> option byte) (model : Model) (cr : credit) (be : bool) : Prop :=
  (exists Rm, PQH.hcore L R0 M0 model0 sp ra LB0 Rm M model)
  /\ getr R (reg 1) = Z_to_bv 64 ra /\ getr R (reg 2) = Z_to_bv 64 sp /\ getr R (reg 8) = getr R0 (reg 8) /\ getr R (reg 10) = Z_to_bv 64 0
  /\ (forall k, In k CSK -> getr R (reg k) = getr R0 (reg k))
  /\ PQH.hstat M true true be /\ (PMST.st_err g = true -> be = true)
  /\ hi_heap HI LB0 cr M (m_vmmaps model)
  /\ PMSP.credit_keep cr0 cr (PQH.P0 L n) PMSP.cr0.

Lemma s_gone :
  PMS.opdel_spec L HI ->
  forall (fx : FPState) R M model cr s be K,
    PQH.H8 L HI R0 M0 model0 sp ra n LB0 cr0 g R M model cr s be -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1,
        H8f R1 M1 model1 cr be ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x3926c M1 model1) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x39240 M model) K.
